const VIEW = "-2 -2 248 311";

/** Grosses Zeichen im Hintergrund (Startseite, Seitenkoepfe). */
export function BrandMark({ className = "" }: { className?: string }) {
  return (
    <svg className={`sj-mark ${className}`} viewBox={VIEW} aria-hidden="true" focusable="false">
      <path className="sj-mark-bands" d={BANDS} />
      <path className="sj-mark-drop" d={DROP} />
    </svg>
  );
}

/**
 * Zeichen der Startseite, das sich beim Laden einmal aufbaut (03.11.26):
 * Der Tropfen faellt, danach oeffnen sich die drei Boegen nacheinander wie
 * ein Faecher. Alle drei Boegen sind Viertelringe um den Punkt (0, 64);
 * jede Maske ist ein dicker Kreisstrich um diesen Punkt, dessen Strich von
 * 0 auf ein Viertel waechst (rechts oben nach links unten). Danach steht
 * alles still. Bei "Bewegung reduzieren" ist es sofort fertig (studio.css).
 */
const ARCS = BANDS.split(/(?=M)/).map((s) => s.trim());

/**
 * Jede Seite baut das Zeichen anders auf (04.11.26, Wunsch Bernard):
 * - fan (Startseite): Tropfen faellt, Boegen oeffnen sich wie ein Faecher
 * - sketch (Ueber mich): feine Goldlinie zeichnet die Form, dann fuellt sie sich
 * - waves (Kontakt): Boegen breiten sich von innen nach aussen aus wie Wellen
 * - forge (Werke): die Boegen erscheinen gluehend golden und kuehlen ab wie Metall
 * - assemble (Design): die Boegen drehen sich herein und rasten ein
 */
export type MarkVariant = "fan" | "sketch" | "waves" | "forge" | "assemble";

export function HeroMark({ id, className = "", variant = "fan" }: { id: string; className?: string; variant?: MarkVariant }) {
  const fan = variant === "fan";
  const arcs = ARCS.map((d, i) => (
    <path key={i} className={`sj-mark-bands sj-arc sj-arc-${i}`} d={d} mask={fan ? `url(#${id}-fan-${i})` : undefined} />
  ));
  const drop = <path className="sj-mark-drop" d={DROP} />;
  return (
    <svg className={`sj-mark is-anim v-${variant} ${className}`} viewBox={VIEW} aria-hidden="true" focusable="false">
      <defs>
        {fan && (
          <>
            {/* weiche Vorderkante: der Maskenstrich ist leicht verwischt und
                beginnt 25 Grad vor den Boegen, damit ihre Kanten scharf bleiben.
                Filterbereich gross, weil er im gedrehten Kreis gilt (sonst
                wird der aeussere Bogen unten links schraeg abgeschnitten). */}
            <filter id={`${id}-feather`} filterUnits="userSpaceOnUse" x="-420" y="-420" width="900" height="980">
              <feGaussianBlur stdDeviation="7" />
            </filter>
            {ARCS.map((_, i) => (
              <mask key={i} id={`${id}-fan-${i}`} maskUnits="userSpaceOnUse" x="-60" y="-60" width="380" height="440">
                <circle
                  className={`sj-fan sj-fan-${i}`}
                  cx="0"
                  cy="64"
                  r="160"
                  fill="none"
                  stroke="#fff"
                  strokeWidth="340"
                  transform="rotate(-25 0 64)"
                  filter={`url(#${id}-feather)`}
                />
              </mask>
            ))}
          </>
        )}
        <clipPath id={`${id}-arcs`}>
          <path d={BANDS} />
        </clipPath>
        <linearGradient id={`${id}-sheen`} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#c9a24f" stopOpacity="0" />
          <stop offset="0.5" stopColor="#c9a24f" stopOpacity="0.6" />
          <stop offset="1" stopColor="#c9a24f" stopOpacity="0" />
        </linearGradient>
        <radialGradient id={`${id}-flame`}>
          <stop offset="0" stopColor="#e9c46a" stopOpacity="0.55" />
          <stop offset="0.45" stopColor="#e9c46a" stopOpacity="0.16" />
          <stop offset="1" stopColor="#e9c46a" stopOpacity="0" />
        </radialGradient>
      </defs>
      {arcs}
      {variant === "sketch" && (
        <g className="sj-sketch">
          {ARCS.map((d, i) => (
            <path key={i} className={`sj-sketch-line sj-sketch-${i}`} d={d} pathLength={1} />
          ))}
          <path className="sj-sketch-line sj-sketch-drop" d={DROP} pathLength={1} />
        </g>
      )}
      {/* einmaliger Lichtschimmer ueber die fertigen Boegen */}
      <g clipPath={`url(#${id}-arcs)`}>
        <g transform="rotate(18 120 180)">
          <rect className="sj-sheen" x="-140" y="-80" width="80" height="520" fill={`url(#${id}-sheen)`} />
        </g>
      </g>
      {/* warmes Leuchten um den Tropfen, nur wenn die Maus nahe ist */}
      <circle className="sj-flame" cx="223.7" cy="24" r="58" fill={`url(#${id}-flame)`} />
      {drop}
    </svg>
  );
}

/** Trenner ueber Ueberschriften: Goldlinie, Tropfen, Goldlinie. */
export function Divider({ className = "" }: { className?: string }) {
  return (
    <div className={`sj-divider ${className}`} aria-hidden="true">
      <span className="sj-divider-line" />
      <svg viewBox="207.5 -1 32.5 47.7" width="11" height="16" focusable="false" className="sj-divider-drop">
        <path d={DROP} />
      </svg>
      <span className="sj-divider-line" />
    </div>
  );
}
